// The integrity trailer on the fixed form (docs/SPEC-TABLES.md §2.14, §3.4
// THE FRAMING): a `fixed table` that declares `integrity = "crc32c"` saves its
// form-3 file with one CRC-32C after the last record, and the reader checks it
// after the form byte and before the layout or any record, so no single-bit
// flip of any byte lands a value. A fixed table without the key writes the
// bytes it wrote before the key existed. The expected bytes and verdicts are
// schema-go's own: the same unit's Go fixed-form surface, generated by the
// gotable emitter and run in a fresh module.
package luautable_test

import (
	"encoding/hex"
	"fmt"
	"maps"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/mas-bandwidth/schema/v2/compiler"
	"github.com/mas-bandwidth/schema/v2/internal/codegen/golang"
	"github.com/mas-bandwidth/schema/v2/internal/codegen/gotable"
	"github.com/mas-bandwidth/schema/v2/internal/codegen/luau/luaurun"
	"github.com/mas-bandwidth/schema/v2/internal/slowtest"
)

const luauFixedIntegritySchema = `package probe
fixed table Reading | integrity = "crc32c"
{
    x int32
    y int16
    label string(8)
}
fixed table PlainReading
{
    x int32
    y int16
    label string(8)
}
`

// goFixedIntegrityProbe is the oracle: it saves the same three records as
// TestGoWireIntegrityFixedForm through the generated Go fixed surface and
// reports the saved bytes and the verdict of every single-bit flip.
const goFixedIntegrityProbe = `package probe
import ("encoding/hex"; "fmt"; "testing")

func fixedValues() ([]Reading, []PlainReading) {
	var r []Reading
	var p []PlainReading
	for k, s := range []string{"ok", "", "eight ch"} {
		var a Reading
		a.X = int32(1000 + k); a.Y = int16(-7 * k); copy(a.Label[:], s); a.LabelLength = int32(len(s))
		r = append(r, a)
		var b PlainReading
		b.X = a.X; b.Y = a.Y; copy(b.Label[:], s); b.LabelLength = int32(len(s))
		p = append(p, b)
	}
	return r, p
}

func TestFixedOracle(t *testing.T) {
	rv, pv := fixedValues()
	kw := make([]byte, ReadingFixedMeasure(3))
	if n := ReadingFixedSave(rv, kw); n != int64(len(kw)) { t.Fatalf("Reading save wrote %d, measure said %d", n, len(kw)) }
	pw := make([]byte, PlainReadingFixedMeasure(3))
	if n := PlainReadingFixedSave(pv, pw); n != int64(len(pw)) { t.Fatalf("PlainReading save wrote %d", n) }
	fmt.Printf("keyed %s\n", hex.EncodeToString(kw))
	fmt.Printf("plain %s\n", hex.EncodeToString(pw))
	for i := range kw {
		for _, x := range []byte{0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0xff} {
			bad := append([]byte(nil), kw...)
			bad[i] ^= x
			var rep TableReport
			n := ReadingFixedLoad(make([]Reading, 4), bad, make([]TableFixedEntry, ReadingFixedPlanMax), &rep)
			reason := rep.Reason
			if n >= 0 { reason = "read" }
			fmt.Printf("flip %d %02x %s\n", i, x, reason)
		}
	}
}
`

const luauFixedIntegrityProbe = `--!strict
local T = require("./ProbeTable")
local F = require("./schema_fixed")

local function hex(b: buffer): string
	local parts = table.create(buffer.len(b))
	for i = 0, buffer.len(b) - 1 do
		parts[i + 1] = string.format("%02x", buffer.readu8(b, i))
	end
	return table.concat(parts)
end

local function reading(k: number): any
	local v = T.ReadingDescriptor.new()
	v.X = 1000 + k
	v.Y = -7 * k
	local s = ({"ok", "", "eight ch"})[k + 1]
	buffer.writestring(v.Label, 0, s)
	v.LabelLength = #s
	return v
end

local function plain(k: number): any
	local v = T.PlainReadingDescriptor.new()
	v.X = 1000 + k
	v.Y = -7 * k
	local s = ({"ok", "", "eight ch"})[k + 1]
	buffer.writestring(v.Label, 0, s)
	v.LabelLength = #s
	return v
end

local readingFixed = { hash = T.ReadingFixedHash, recordBytes = T.ReadingFixedRecordBytes, layout = T.ReadingFixedLayout }
local plainFixed = { hash = T.PlainReadingFixedHash, recordBytes = T.PlainReadingFixedRecordBytes, layout = T.PlainReadingFixedLayout }

local keyed = F.save(T.ReadingDescriptor, readingFixed, { reading(0), reading(1), reading(2) })
local keyless = F.save(T.PlainReadingDescriptor, plainFixed, { plain(0), plain(1), plain(2) })
print("keyed " .. hex(keyed))
print("plain " .. hex(keyless))

local back = F.load(T.ReadingDescriptor, readingFixed, keyed)
print("records " .. tostring(#back))
for i = 1, #back do
	print(string.format("value %d %d %d %d", i, back[i].X, back[i].Y, back[i].LabelLength, back[i].X * 0))
end

for i = 0, buffer.len(keyed) - 1 do
	for _, x in { 0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0xff } do
		local bad = buffer.create(buffer.len(keyed))
		buffer.copy(bad, 0, keyed, 0, buffer.len(keyed))
		buffer.writeu8(bad, i, bit32.bxor(buffer.readu8(bad, i), x))
		local ok, err = pcall(F.load, T.ReadingDescriptor, readingFixed, bad)
		local verdict = "read"
		if not ok then
			if type(err) == "table" and (err :: any).name ~= nil then
				verdict = (err :: any).name
			else
				verdict = "error"
			end
		end
		print(string.format("flip %d %02x %s", i, x, verdict))
	end
end
`

// goFixedIntegrityOracle builds the same unit for Go, compiles the generated
// fixed surface in a fresh module against the pinned runtime, and returns the
// keyed and keyless saves plus every flip's verdict.
func goFixedIntegrityOracle(t *testing.T, schema string) (keyed, keyless []byte, verdicts map[string]string) {
	t.Helper()
	dir := t.TempDir()
	schemaPath := filepath.Join(dir, "Probe.schema")
	if err := os.WriteFile(schemaPath, []byte(schema), 0o644); err != nil {
		t.Fatal(err)
	}
	u, err := compiler.New().Load([]string{schemaPath})
	if err != nil {
		t.Fatal(err)
	}
	files, err := golang.Generate(u)
	if err != nil {
		t.Fatal(err)
	}
	tables, err := gotable.Generate(u)
	if err != nil {
		t.Fatal(err)
	}
	maps.Copy(files, tables)
	// Only a unit whose generated package imports the packet runtime needs the
	// pinned serialize.go replace; the fixed surface alone does not.
	mod := "module probe\n\ngo 1.26\n"
	needsRuntime := false
	for _, data := range files {
		if strings.Contains(string(data), `"github.com/mas-bandwidth/serialize.go"`) {
			needsRuntime = true
			break
		}
	}
	if needsRuntime {
		runtime := slowtest.SerializeGo(t, root)
		mod += fmt.Sprintf("\nrequire github.com/mas-bandwidth/serialize.go v0.0.0\nreplace github.com/mas-bandwidth/serialize.go => %q\n", runtime)
	}
	files["go.mod"] = []byte(mod)
	files["oracle_test.go"] = []byte(goFixedIntegrityProbe)
	for name, data := range files {
		if err := os.WriteFile(filepath.Join(dir, name), data, 0o644); err != nil {
			t.Fatal(err)
		}
	}
	cmd := exec.Command("nice", "-n", "19", "go", "test", "-v", "-count=1", "-timeout", "600s", ".")
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), "GOFLAGS=-mod=readonly")
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("the generated Go oracle failed: %v\n%s", err, out)
	}
	verdicts = map[string]string{}
	for line := range strings.SplitSeq(string(out), "\n") {
		f := strings.Fields(line)
		if len(f) == 0 {
			continue
		}
		switch f[0] {
		case "keyed":
			keyed, err = hex.DecodeString(f[1])
			if err != nil {
				t.Fatalf("the oracle's keyed hex: %v", err)
			}
		case "plain":
			keyless, err = hex.DecodeString(f[1])
			if err != nil {
				t.Fatalf("the oracle's plain hex: %v", err)
			}
		case "flip":
			if len(f) != 4 {
				t.Fatalf("unexpected oracle flip line %q", line)
			}
			verdicts[f[1]+" "+f[2]] = f[3]
		}
	}
	if len(keyed) == 0 || len(keyless) == 0 || len(verdicts) == 0 {
		t.Fatalf("the oracle printed no rows:\n%s", out)
	}
	return keyed, keyless, verdicts
}

// TestLuauFixedFormIntegrity pins §2.14's fixed-form trailer: the declaring
// table's save is the keyless file plus the CRC-32C of every byte before it,
// the keyless file is unchanged, and every flip keeps the form byte's name or
// refuses integrity_mismatch with nothing landed.
func TestLuauFixedFormIntegrity(t *testing.T) {
	slowtest.Gate(t, "the pinned Luau interpreter and the schema-go oracle")
	t.Parallel()
	wantKeyed, wantKeyless, wantVerdicts := goFixedIntegrityOracle(t, luauFixedIntegritySchema)

	g := generateFiles(t, map[string]string{"Probe.schema": luauFixedIntegritySchema})
	if err := os.WriteFile(filepath.Join(g.dir, "main.luau"), []byte(luauFixedIntegrityProbe), 0o644); err != nil {
		t.Fatal(err)
	}
	out := string(luaurun.Run(t, g.dir, "main.luau", nil))

	var gotKeyed, gotKeyless []byte
	gotVerdicts := map[string]string{}
	records, values := -1, 0
	for line := range strings.SplitSeq(out, "\n") {
		f := strings.Fields(line)
		if len(f) == 0 {
			continue
		}
		switch f[0] {
		case "keyed":
			var err error
			gotKeyed, err = hex.DecodeString(f[1])
			if err != nil {
				t.Fatalf("Luau keyed hex: %v", err)
			}
		case "plain":
			var err error
			gotKeyless, err = hex.DecodeString(f[1])
			if err != nil {
				t.Fatalf("Luau plain hex: %v", err)
			}
		case "records":
			if _, err := fmt.Sscanf(f[1], "%d", &records); err != nil {
				t.Fatalf("Luau record count %q: %v", f[1], err)
			}
		case "value":
			values++
		case "flip":
			if len(f) != 4 {
				t.Fatalf("unexpected Luau flip line %q", line)
			}
			gotVerdicts[f[1]+" "+f[2]] = f[3]
		}
	}
	if len(gotKeyed) == 0 || len(gotKeyless) == 0 {
		t.Fatalf("the Luau probe printed no saves:\n%s", out)
	}
	if string(gotKeyed) != string(wantKeyed) {
		t.Errorf("Reading save is not the Go fixed golden: got %d bytes %x, want %d bytes %x", len(gotKeyed), gotKeyed, len(wantKeyed), wantKeyed)
	}
	if string(gotKeyless) != string(wantKeyless) {
		t.Errorf("PlainReading moved from its keyless golden: got %d bytes %x, want %d bytes %x", len(gotKeyless), gotKeyless, len(wantKeyless), wantKeyless)
	}
	if records != 3 || values != 3 {
		t.Errorf("round trip landed %d records (%d value rows), want 3", records, values)
	}
	if len(gotVerdicts) != len(wantVerdicts) {
		t.Fatalf("the Luau probe reported %d flips, the Go oracle %d", len(gotVerdicts), len(wantVerdicts))
	}
	bad := 0
	for key, want := range wantVerdicts {
		if got := gotVerdicts[key]; got != want {
			bad++
			if bad <= 10 {
				t.Errorf("byte/flip %s: Luau answered %q, Go answered %q", key, got, want)
			}
		}
	}
	if bad > 0 {
		t.Fatalf("%d of %d flips disagree with the Go oracle", bad, len(wantVerdicts))
	}
	t.Logf("Reading %d bytes, %d flips agree with the Go oracle", len(gotKeyed), len(gotVerdicts))
}
